var row = $input.first().json || {};
var cv = '';
try { cv = $('CV Source').first().json.cv_text || ''; } catch (e) { cv = ''; }
var company = row.company || 'the company';
var industry = row.industry || 'Engineering';
var recipient = row.contact_email || row.email || '';
var hasJd = row.job_description && String(row.job_description).trim().length > 0;
var jd = hasJd ? String(row.job_description) : ('General open application to ' + company + ', a Saudi Arabia-based ' + industry + ' company. Target role: Industrial Engineer focused on process optimization, supply chain logistics, operations management, quality and safety compliance.');
var analystSystem = 'You are a Job Analyzer. Extract structured data from the job/company context. Respond ONLY with compact JSON: {"top_skills":[5 strings],"key_qualifications":[3 strings],"industry_keywords":[strings],"company_tone":"one word"}.';
var analystUser = 'Company: ' + company + ' Industry: ' + industry + ' Context: ' + jd;
var groqBody = { model: 'llama-3.3-70b-versatile', temperature: 0.3, response_format: { type: 'json_object' }, messages: [ { role: 'system', content: analystSystem }, { role: 'user', content: analystUser } ] };
var nvidiaBody = { model: 'meta/llama-3.1-70b-instruct', temperature: 0.3, messages: [ { role: 'system', content: analystSystem }, { role: 'user', content: analystUser } ] };
return [{ json: { row_id: row.id, company: company, industry: industry, recipient: recipient, job_description: jd, cv_text: cv, groqBody: groqBody, nvidiaBody: nvidiaBody } }];

var all = $input.all();
var vec = [];
for (var i = 0; i < all.length; i++) {
  var v = all[i].json;
  if (typeof v === "number") { vec.push(v); }
  else if (Array.isArray(v)) { for (var k = 0; k < v.length; k++) { if (typeof v[k] === "number") vec.push(v[k]); } }
}
return [{ json: { embedding: vec, dim: vec.length } }];

var LF = String.fromCharCode(10);
var prep = $('Prep Inputs').first().json || {};
var matches = [];
try { var q = $('Pinecone Query').first().json || {}; matches = q.matches || []; } catch (e) { matches = []; }
var lines = [];
for (var i = 0; i < matches.length; i++) { var m = matches[i] || {}; var md = m.metadata || {}; lines.push('- ' + (md.company || '?') + ': outcome ' + (md.status || 'n/a')); }
var memText = lines.length ? lines.join(LF) : 'No similar past jobs found in memory.';
return [{ json: { row_id: prep.row_id, company: prep.company, memory_context: memText, groqBody: prep.groqBody } }];

var FENCE = String.fromCharCode(96);
var src = $input.first().json || {};
var prep = $('Prep Inputs').first().json || {};
var mem = '';
try { mem = $('Build Memory').first().json.memory_context || ''; } catch (e) { mem = ''; }
// parse the merged analyzer output (Groq or NVIDIA, both OpenAI-compatible)
var content = '';
try { content = src.choices[0].message.content; } catch (e) { content = ''; }
var analysis = {};
if (content) {
  var clean = String(content).split(FENCE).join('').trim();
  if (clean.slice(0, 4).toLowerCase() === 'json') clean = clean.slice(4).trim();
  try { analysis = JSON.parse(clean); } catch (e) { analysis = { raw: content }; }
}
// deterministic task plan
var plan = { cv_agent: 'groq', cv_fallback: 'zai', cover_agent: 'groq', cover_fallback: 'zai', last_resort: 'openai', enrich_agent: 'gemini', quality_check: true };
var ctx = 'Company: ' + prep.company + ' Industry: ' + prep.industry + ' Job analysis JSON: ' + JSON.stringify(analysis) + ' Past memory: ' + mem;
// CV tailoring prompt
var cvSys = 'You are the CV tailor for candidate Hassan Ahmed Adam Mohammad, an Industrial Engineer in Jeddah. Rewrite the base CV as plain text, emphasizing matching experience, reordering bullets, and inserting relevant keywords from the job analysis. Do not fabricate experience. Respond ONLY with compact JSON: {"tailored_cv":"...plain text..."}.';
var cvUsr = ctx + ' Base CV: ' + prep.cv_text;
var cvMsgs = [ { role: 'system', content: cvSys }, { role: 'user', content: cvUsr } ];
var cvGroqBody = { model: 'llama-3.3-70b-versatile', temperature: 0.6, max_tokens: 1800, response_format: { type: 'json_object' }, messages: cvMsgs };
var cvZaiBody = { model: 'glm-4-flash', temperature: 0.6, max_tokens: 1800, messages: cvMsgs };
var cvOpenaiBody = { model: 'gpt-4o-mini', temperature: 0.6, max_tokens: 1800, response_format: { type: 'json_object' }, messages: cvMsgs };
// Cover letter prompt
var clSys = 'You are the cover letter writer for candidate Hassan Ahmed Adam Mohammad, an Industrial Engineer in Jeddah. Write a cover letter under 200 words with three paragraphs: opening interest, middle mapping his experience to the role, closing call-to-action. Respond ONLY with compact JSON: {"cover_letter":"..."}.';
var clUsr = ctx + ' Candidate background: ' + String(prep.cv_text || '').slice(0, 1200);
var clMsgs = [ { role: 'system', content: clSys }, { role: 'user', content: clUsr } ];
var coverGroqBody = { model: 'llama-3.3-70b-versatile', temperature: 0.6, max_tokens: 900, response_format: { type: 'json_object' }, messages: clMsgs };
var coverZaiBody = { model: 'glm-4-flash', temperature: 0.6, max_tokens: 900, messages: clMsgs };
var coverOpenaiBody = { model: 'gpt-4o-mini', temperature: 0.6, max_tokens: 900, response_format: { type: 'json_object' }, messages: clMsgs };
return [{ json: { row_id: prep.row_id, company: prep.company, recipient: prep.recipient, analysis: analysis, plan: plan, cvGroqBody: cvGroqBody, cvZaiBody: cvZaiBody, cvOpenaiBody: cvOpenaiBody, coverGroqBody: coverGroqBody, coverZaiBody: coverZaiBody, coverOpenaiBody: coverOpenaiBody } }];

var FENCE = String.fromCharCode(96);
var tr = $('Task Router').first().json || {};
var src = $input.first().json || {};
var content = '';
try { content = src.choices[0].message.content; } catch (e) { content = ''; }
var clean = String(content).split(FENCE).join('').trim();
if (clean.slice(0, 4).toLowerCase() === 'json') clean = clean.slice(4).trim();
var out = {};
try { out = JSON.parse(clean); } catch (e) { out = { tailored_cv: content }; }
return [{ json: { row_id: tr.row_id, company: tr.company, recipient: tr.recipient, tailored_cv: out.tailored_cv || content || '', cv_agent: 'groq' } }];

