var hf = $input.first().json;
var pk = $('Merge Cover').first().json || {};
var isNeg = false;
var score = 0.9;
try {
  var arr = hf;
  if (Array.isArray(arr) && Array.isArray(arr[0])) arr = arr[0];
  if (Array.isArray(arr)) {
    var top = arr[0];
    for (var i = 0; i < arr.length; i++) { if (arr[i] && arr[i].score > top.score) top = arr[i]; }
    var lbl = String(top.label || '').toLowerCase();
    if ((lbl === 'negative' || lbl === 'label_0') && top.score >= 0.6) { isNeg = true; score = 0.4; }
    else { score = 0.9; }
  }
} catch (e) { isNeg = false; score = 0.9; }
return [{ json: { row_id: pk.row_id, company: pk.company, recipient: pk.recipient, tailored_cv: pk.tailored_cv || '', cover_letter: pk.cover_letter || '', cv_agent: pk.cv_agent || '', cover_agent: pk.cover_agent || '', tone_score: score, tone_flagged: isNeg, tone_source: 'hf-roberta' } }];

var pk = $('Merge Cover').first().json || {};
var text = ((pk.cover_letter || '') + ' ' + (pk.tailored_cv || '')).toLowerCase();
var negs = ['unfortunately','regret','sorry','cannot','can\u2019t','unable','not qualified','lack of','no experience','weak','poor','fail','failed','problem','difficult','concern','worried','desperate','beg','pity'];
var flagged = false;
for (var i = 0; i < negs.length; i++) { if (text.indexOf(negs[i]) !== -1) { flagged = true; break; } }
var score = flagged ? 0.4 : 0.9;
return [{ json: { row_id: pk.row_id, company: pk.company, recipient: pk.recipient, tailored_cv: pk.tailored_cv || '', cover_letter: pk.cover_letter || '', cv_agent: pk.cv_agent || '', cover_agent: pk.cover_agent || '', tone_score: score, tone_flagged: flagged, tone_source: 'simple-code' } }];

var j = $input.first().json || {};
var sys = 'You are the final reviewer and polisher for a job application. Ensure the CV is clean plain text and the cover letter is confident, warm, professional, and under 200 words. Fix any tone issues. Do not fabricate experience. Respond ONLY with compact JSON: {"tailored_cv":"...","cover_letter":"..."}.';
var usr = 'Company: ' + (j.company || '') + ' Tone score: ' + (j.tone_score) + ' (flagged=' + (j.tone_flagged) + '). CV: ' + (j.tailored_cv || '') + ' Cover letter: ' + (j.cover_letter || '');
var reviewBody = { model: 'llama-3.3-70b-versatile', temperature: 0.4, max_tokens: 1800, response_format: { type: 'json_object' }, messages: [ { role: 'system', content: sys }, { role: 'user', content: usr } ] };
return [{ json: { row_id: j.row_id, company: j.company, recipient: j.recipient, tailored_cv: j.tailored_cv || '', cover_letter: j.cover_letter || '', cv_agent: j.cv_agent || '', cover_agent: j.cover_agent || '', tone_score: j.tone_score, reviewBody: reviewBody } }];

var FENCE = String.fromCharCode(96);
var src = $input.first().json || {};
var prev = $('Build Review Body').first().json || {};
var content = '';
try { content = src.choices[0].message.content; } catch (e) { content = ''; }
var out = {};
if (content) {
  var clean = String(content).split(FENCE).join('').trim();
  if (clean.slice(0, 4).toLowerCase() === 'json') clean = clean.slice(4).trim();
  try { out = JSON.parse(clean); } catch (e) { out = {}; }
}
return [{ json: { row_id: prev.row_id, company: prev.company, recipient: prev.recipient, tailored_cv: out.tailored_cv || prev.tailored_cv || '', cover_letter: out.cover_letter || prev.cover_letter || '', cv_agent: prev.cv_agent || '', cover_agent: prev.cover_agent || '' } }];

var j = $input.first().json || {};
var esc = function (s) { return String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
var LF = String.fromCharCode(10);
var cvHtml = esc(j.tailored_cv).split(LF).join('<br>');
var coverHtml = esc(j.cover_letter).split(LF).join('<br>');
var html = '<html><head><meta charset="utf-8"><style>body{font-family:Helvetica,Arial,sans-serif;font-size:12px;line-height:1.5;color:#222;margin:40px;}</style></head><body>' + cvHtml + '</body></html>';
return [{ json: { row_id: j.row_id, company: j.company, recipient: j.recipient, tailored_cv: j.tailored_cv || '', cover_letter: j.cover_letter || '', cv_agent: j.cv_agent || '', cover_agent: j.cover_agent || '', cover_html: coverHtml, html: html } }];

var bh = $('Build CV HTML').first().json || {};
var b64 = '';
try {
  var buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  b64 = buf.toString('base64');
} catch (e) { b64 = ''; }
var coverHtml = bh.cover_html || '';
var brevoBody = {
  sender: { name: 'Hassan Ahmed Adam Mohammad', email: 'jobapplier@agentmail.to' },
  to: [{ email: bh.recipient }],
  subject: 'Application for Industrial Engineering Position - Hassan Adam',
  htmlContent: '<html><body style="font-family:Helvetica,Arial,sans-serif;font-size:14px;color:#222;">' + coverHtml + '</body></html>',
  attachment: [{ content: b64, name: 'CV_Hassan_Adam.pdf' }]
};
return [{ json: { row_id: bh.row_id, recipient: bh.recipient, company: bh.company, cv_agent: bh.cv_agent, cover_agent: bh.cover_agent, pdf_bytes: b64.length, brevoBody: brevoBody } }];

var src = $input.first().json || {};
var eb = $('Encode PDF + Build Brevo').first().json || {};
var bh = $('Build CV HTML').first().json || {};
var messageId = src.messageId || (src.messageIds && src.messageIds[0]) || '';
var status = messageId ? 'success' : 'failed';
return [{ json: { row_id: eb.row_id, recipient: eb.recipient, company: bh.company, tailored_cv: bh.tailored_cv, cover_letter: bh.cover_letter, cv_agent: eb.cv_agent || '', cover_agent: eb.cover_agent || '', messageId: messageId, status: status } }];

var pb = $input.first().json || {};
var prep = $('Prep Inputs').first().json || {};
var vec = [];
try { vec = $('Aggregate Embedding').first().json.embedding || []; } catch (err) { vec = []; }
var host = '';
try { host = $('Pinecone Describe Index').first().json.host || ''; } catch (e) { host = ''; }
if (!host) { try { host = $('Pinecone Create Index').first().json.host || ''; } catch (e) { host = ''; } }
if (!host) { host = 'job-agent-memory-kwj37r9.svc.aped-4627-b74a.pinecone.io'; }
var ts = new Date().toISOString();
var upsertBody = { vectors: [{ id: 'job-' + (pb.row_id || Date.now()), values: vec, metadata: { company: pb.company || '', job_description: String(prep.job_description || '').slice(0, 1000), tailored_cv: String(pb.tailored_cv || '').slice(0, 2000), cover_letter: String(pb.cover_letter || '').slice(0, 1000), status: pb.status || '', cv_agent: pb.cv_agent || '', cover_agent: pb.cover_agent || '', timestamp: ts } }] };
return [{ json: { host: host, has_host: host.length > 0, dim: vec.length, upsertBody: upsertBody } }];

var up = $input.first().json || {};
var pb = $('Parse Brevo Result').first().json || {};
var upserted = 0;
try { upserted = up.upsertedCount; } catch (e) { upserted = 0; }
if (typeof upserted !== 'number') upserted = 0;
var pineStatus = upserted > 0 ? ('Pinecone upsert OK (' + upserted + ' vector)') : 'Pinecone upsert not confirmed';
var LF = String.fromCharCode(10);
var tgText = 'Application ' + (pb.status || 'unknown') + ' to ' + (pb.company || 'the company') + ' at ' + (pb.recipient || '') + LF + 'Brevo message ID: ' + (pb.messageId || 'n/a') + LF + 'CV agent: ' + (pb.cv_agent || '?') + ' | Cover agent: ' + (pb.cover_agent || '?') + LF + pineStatus;
return [{ json: { messageId: pb.messageId, status: pb.status, company: pb.company, recipient: pb.recipient, cv_agent: pb.cv_agent, cover_agent: pb.cover_agent, pinecone_upserted: upserted, tgText: tgText } }];
